-- Aprenda se Divertindo · 88 · Simulado 1 da Trilha Policial
-- Rode depois do 87-ranking-mensal.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o primeiro Simulado de Domingo da trilha Policial: domingo, 25/10/2026, das 0h às 23h59.
-- 60 questões de A a E, estilo AOCP, 3 horas de prova. Gabarito comentado liberado na segunda, às 0h.
-- Rodar de novo atualiza as questões, desde que ninguém tenha começado a prova.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "A investigação criminal moderna depende cada vez menos da confissão e cada vez mais da prova técnica. Câmeras, registros de celulares e exames de DNA permitem reconstruir fatos que, há poucas décadas, só podiam ser contados por testemunhas. Essa mudança, contudo, não torna o investigador dispensável. Ao contrário: quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante, de relacionar indícios aparentemente isolados e de preservar cada vestígio para que ele possa ser usado no processo.\n\nHá, porém, um risco. A confiança excessiva na tecnologia pode levar à ilusão de que os números falam por si. Um laudo mal interpretado ou uma imagem retirada de contexto podem conduzir a conclusões tão equivocadas quanto um depoimento falso. Por isso, a boa investigação continua sendo, antes de tudo, um exercício de método: formular hipóteses, testá-las e abandonar aquelas que os fatos não sustentam.", "enunciado": "De acordo com o texto, é correto afirmar que", "opcoes": ["a confissão deixou de ter qualquer valor na investigação criminal.", "o grande volume de dados torna o trabalho do investigador desnecessário.", "a prova técnica é infalível, ao contrário do depoimento de testemunhas.", "os números, por si sós, bastam para esclarecer qualquer crime.", "a tecnologia ampliou os meios de prova, mas não dispensa o método e o julgamento do investigador."], "gabarito": 4, "explicacao": "O texto afirma que a mudança 'não torna o investigador dispensável' e que a boa investigação continua sendo 'um exercício de método'. Ele também alerta que laudos e imagens podem levar a conclusões equivocadas, o que afasta a ideia de infalibilidade."}, {"materia": "port", "texto_base": "A investigação criminal moderna depende cada vez menos da confissão e cada vez mais da prova técnica. Câmeras, registros de celulares e exames de DNA permitem reconstruir fatos que, há poucas décadas, só podiam ser contados por testemunhas. Essa mudança, contudo, não torna o investigador dispensável. Ao contrário: quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante, de relacionar indícios aparentemente isolados e de preservar cada vestígio para que ele possa ser usado no processo.\n\nHá, porém, um risco. A confiança excessiva na tecnologia pode levar à ilusão de que os números falam por si. Um laudo mal interpretado ou uma imagem retirada de contexto podem conduzir a conclusões tão equivocadas quanto um depoimento falso. Por isso, a boa investigação continua sendo, antes de tudo, um exercício de método: formular hipóteses, testá-las e abandonar aquelas que os fatos não sustentam.", "enunciado": "No trecho \"Essa mudança, contudo, não torna o investigador dispensável\", a palavra \"contudo\" pode ser substituída, sem alteração de sentido, por", "opcoes": ["portanto", "porque", "além disso", "no entanto", "desde que"], "gabarito": 3, "explicacao": "\"Contudo\" é conjunção adversativa, assim como \"no entanto\". \"Portanto\" é conclusiva, \"porque\" é causal, \"além disso\" é aditiva e \"desde que\" é condicional."}, {"materia": "port", "texto_base": "A investigação criminal moderna depende cada vez menos da confissão e cada vez mais da prova técnica. Câmeras, registros de celulares e exames de DNA permitem reconstruir fatos que, há poucas décadas, só podiam ser contados por testemunhas. Essa mudança, contudo, não torna o investigador dispensável. Ao contrário: quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante, de relacionar indícios aparentemente isolados e de preservar cada vestígio para que ele possa ser usado no processo.\n\nHá, porém, um risco. A confiança excessiva na tecnologia pode levar à ilusão de que os números falam por si. Um laudo mal interpretado ou uma imagem retirada de contexto podem conduzir a conclusões tão equivocadas quanto um depoimento falso. Por isso, a boa investigação continua sendo, antes de tudo, um exercício de método: formular hipóteses, testá-las e abandonar aquelas que os fatos não sustentam.", "enunciado": "No trecho \"quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante\", a relação estabelecida entre as ideias é de", "opcoes": ["condição", "proporção", "causa", "finalidade", "concessão"], "gabarito": 1, "explicacao": "A estrutura \"quanto maior..., mais...\" expressa proporcionalidade: uma coisa cresce à medida que a outra cresce."}, {"materia": "port", "texto_base": "A investigação criminal moderna depende cada vez menos da confissão e cada vez mais da prova técnica. Câmeras, registros de celulares e exames de DNA permitem reconstruir fatos que, há poucas décadas, só podiam ser contados por testemunhas. Essa mudança, contudo, não torna o investigador dispensável. Ao contrário: quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante, de relacionar indícios aparentemente isolados e de preservar cada vestígio para que ele possa ser usado no processo.\n\nHá, porém, um risco. A confiança excessiva na tecnologia pode levar à ilusão de que os números falam por si. Um laudo mal interpretado ou uma imagem retirada de contexto podem conduzir a conclusões tão equivocadas quanto um depoimento falso. Por isso, a boa investigação continua sendo, antes de tudo, um exercício de método: formular hipóteses, testá-las e abandonar aquelas que os fatos não sustentam.", "enunciado": "No trecho \"abandonar aquelas que os fatos não sustentam\", o pronome \"aquelas\" retoma", "opcoes": ["provas", "testemunhas", "conclusões", "imagens", "hipóteses"], "gabarito": 4, "explicacao": "O período fala em \"formular hipóteses, testá-las e abandonar aquelas\": o pronome retoma \"hipóteses\"."}, {"materia": "port", "texto_base": "A investigação criminal moderna depende cada vez menos da confissão e cada vez mais da prova técnica. Câmeras, registros de celulares e exames de DNA permitem reconstruir fatos que, há poucas décadas, só podiam ser contados por testemunhas. Essa mudança, contudo, não torna o investigador dispensável. Ao contrário: quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante, de relacionar indícios aparentemente isolados e de preservar cada vestígio para que ele possa ser usado no processo.\n\nHá, porém, um risco. A confiança excessiva na tecnologia pode levar à ilusão de que os números falam por si. Um laudo mal interpretado ou uma imagem retirada de contexto podem conduzir a conclusões tão equivocadas quanto um depoimento falso. Por isso, a boa investigação continua sendo, antes de tudo, um exercício de método: formular hipóteses, testá-las e abandonar aquelas que os fatos não sustentam.", "enunciado": "No trecho \"preservar cada vestígio para que ele possa ser usado no processo\", a oração destacada por \"para que\" expressa", "opcoes": ["condição", "causa", "consequência", "finalidade", "tempo"], "gabarito": 3, "explicacao": "\"Para que\" é conjunção final: indica o objetivo de preservar o vestígio."}, {"materia": "port", "texto_base": "A investigação criminal moderna depende cada vez menos da confissão e cada vez mais da prova técnica. Câmeras, registros de celulares e exames de DNA permitem reconstruir fatos que, há poucas décadas, só podiam ser contados por testemunhas. Essa mudança, contudo, não torna o investigador dispensável. Ao contrário: quanto maior o volume de dados, mais importante se torna a capacidade de selecionar o que é relevante, de relacionar indícios aparentemente isolados e de preservar cada vestígio para que ele possa ser usado no processo.\n\nHá, porém, um risco. A confiança excessiva na tecnologia pode levar à ilusão de que os números falam por si. Um laudo mal interpretado ou uma imagem retirada de contexto podem conduzir a conclusões tão equivocadas quanto um depoimento falso. Por isso, a boa investigação continua sendo, antes de tudo, um exercício de método: formular hipóteses, testá-las e abandonar aquelas que os fatos não sustentam.", "enunciado": "No trecho \"pode levar à ilusão de que os números falam por si\", a oração \"de que os números falam por si\" classifica-se como", "opcoes": ["subordinada adverbial causal", "subordinada substantiva objetiva direta", "subordinada adjetiva restritiva", "subordinada substantiva completiva nominal", "subordinada adjetiva explicativa"], "gabarito": 3, "explicacao": "A oração completa o sentido do substantivo \"ilusão\" e vem introduzida por preposição (\"de que\"): é substantiva completiva nominal."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que o acento indicativo de crase está empregado corretamente.", "opcoes": ["Entregou o relatório à seu chefe.", "O investigador referiu-se à testemunha que chegou às 9h.", "A viatura começou à andar devagar.", "O delegado fez referência à pessoas suspeitas.", "Os agentes foram à pé até o local."], "gabarito": 1, "explicacao": "\"Referir-se a\" + \"a testemunha\" gera crase, e \"às 9h\" indica hora determinada. Não há crase antes de pronome possessivo masculino, de verbo, de palavra no plural precedida só de \"a\" nem na expressão \"a pé\"."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa que está de acordo com a norma-padrão quanto à concordância verbal.", "opcoes": ["Haviam muitos suspeitos no local do crime.", "Existe vários registros da ocorrência.", "Fazia dois anos que o caso estava parado.", "Fazem três meses que o inquérito foi aberto.", "Devem haver novas provas no processo."], "gabarito": 2, "explicacao": "\"Fazer\" indicando tempo decorrido e \"haver\" no sentido de existir são impessoais e ficam no singular, e o auxiliar acompanha: \"deve haver\". \"Existir\" é pessoal e concorda com o sujeito: \"existem vários registros\"."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que a regência verbal está de acordo com a norma-padrão.", "opcoes": ["Os agentes não obedeceram o regulamento.", "Prefiro investigar do que esperar.", "O escrivão aspirava o cargo de delegado.", "Esqueci do horário da audiência.", "O delegado assistiu ao vídeo das câmeras de segurança."], "gabarito": 4, "explicacao": "\"Assistir\" no sentido de ver exige a preposição \"a\". Na norma-padrão, obedece-se \"a\" algo, prefere-se uma coisa \"a\" outra, esquece-se algo (ou esquece-se \"de\" algo, com pronome) e aspira-se \"a\" um cargo."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que a colocação do pronome oblíquo átono está de acordo com a norma-padrão.", "opcoes": ["Quem avisou-te da operação?", "Me disseram que o suspeito fugiu.", "Nunca entregaram-me o laudo.", "Farei-te uma pergunta sobre o caso.", "Não se sabe quem fez a denúncia."], "gabarito": 4, "explicacao": "Palavras negativas (\"não\", \"nunca\") e pronomes interrogativos atraem o pronome (próclise). A norma-padrão não inicia período com pronome oblíquo, e o futuro do presente pede mesóclise (\"far-te-ei\")."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa corretamente pontuada.", "opcoes": ["A testemunha disse que, iria depor amanhã.", "Os investigadores após longa diligência, localizaram o veículo.", "Os investigadores, após longa diligência, localizaram o veículo.", "O delegado, determinou a realização da perícia.", "Os agentes encontraram, a arma no carro."], "gabarito": 2, "explicacao": "A expressão intercalada \"após longa diligência\" deve ficar entre duas vírgulas. Não se separa por vírgula o sujeito do verbo, o verbo do complemento nem a conjunção integrante da oração que ela introduz."}, {"materia": "port", "texto_base": null, "enunciado": "Ao passar a frase \"A perícia analisou as amostras\" para a voz passiva analítica, obtém-se:", "opcoes": ["As amostras analisaram a perícia.", "A perícia tinha analisado as amostras.", "As amostras foram analisadas pela perícia.", "A perícia foi analisada pelas amostras.", "Analisaram-se as amostras."], "gabarito": 2, "explicacao": "Na voz passiva analítica, o objeto vira sujeito, usa-se \"ser\" + particípio no mesmo tempo (\"analisou\" → \"foram analisadas\") e o antigo sujeito vira agente da passiva. \"Analisaram-se as amostras\" é passiva sintética."}, {"materia": "rl", "texto_base": null, "enunciado": "A negação da proposição \"Todo policial é honesto\" é:", "opcoes": ["Algum policial não é honesto.", "Algum policial é honesto.", "Nenhum policial é honesto.", "Todo policial é desonesto.", "Nenhum policial é desonesto."], "gabarito": 0, "explicacao": "A negação de \"todo A é B\" é \"algum A não é B\": basta um caso contrário para a afirmação geral ser falsa."}, {"materia": "rl", "texto_base": null, "enunciado": "A negação da proposição \"Se chove, então a rua fica molhada\" é:", "opcoes": ["Se não chove, então a rua não fica molhada.", "Não chove ou a rua fica molhada.", "Se a rua não fica molhada, então não chove.", "Não chove e a rua não fica molhada.", "Chove e a rua não fica molhada."], "gabarito": 4, "explicacao": "A negação de \"se p, então q\" é \"p e não q\". As alternativas \"não chove ou a rua fica molhada\" e \"se a rua não fica molhada, então não chove\" são equivalentes à proposição original, não sua negação."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma proposição equivalente a \"Se é investigador, então fez concurso\" é:", "opcoes": ["Se fez concurso, então é investigador.", "Se não é investigador, então não fez concurso.", "Se não fez concurso, então não é investigador.", "É investigador e não fez concurso.", "É investigador ou fez concurso."], "gabarito": 2, "explicacao": "A contrapositiva \"se não q, então não p\" é equivalente a \"se p, então q\". A recíproca e a inversa não são equivalentes, e \"p e não q\" é a negação."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma proposição composta formada por 4 proposições simples distintas tem tabela-verdade com quantas linhas?", "opcoes": ["4", "8", "12", "32", "16"], "gabarito": 4, "explicacao": "O número de linhas é 2ⁿ: 2⁴ = 16."}, {"materia": "rl", "texto_base": null, "enunciado": "De quantas maneiras é possível formar uma equipe de 3 agentes escolhidos entre 7 disponíveis, sem distinção de funções na equipe?", "opcoes": ["210", "42", "21", "343", "35"], "gabarito": 4, "explicacao": "A ordem não importa, então é combinação: C(7,3) = 7 × 6 × 5 ÷ (3 × 2 × 1) = 35. O valor 210 seria o arranjo, em que a ordem importa."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma urna tem 4 bolas vermelhas e 6 azuis. Retirando-se 2 bolas ao acaso, sem reposição, a probabilidade de as duas serem vermelhas é:", "opcoes": ["1/15", "2/5", "2/15", "1/5", "4/25"], "gabarito": 2, "explicacao": "P = 4/10 × 3/9 = 12/90 = 2/15. O valor 4/25 seria o resultado com reposição (4/10 × 4/10)."}, {"materia": "inf", "texto_base": null, "enunciado": "No Microsoft Word e na maioria dos programas para Windows, o atalho Ctrl + Z serve para", "opcoes": ["selecionar todo o conteúdo.", "refazer a última ação desfeita.", "desfazer a última ação.", "salvar o arquivo.", "fechar o programa."], "gabarito": 2, "explicacao": "Ctrl + Z desfaz. Ctrl + S (ou Ctrl + B no Word em português) salva, Ctrl + Y refaz e Ctrl + A (ou Ctrl + T no Word em português) seleciona tudo."}, {"materia": "inf", "texto_base": null, "enunciado": "A fraude em que o criminoso envia mensagem fingindo ser um banco ou órgão público para levar a vítima a informar senhas ou dados pessoais é chamada de", "opcoes": ["firewall.", "phishing.", "worm.", "ransomware.", "backup."], "gabarito": 1, "explicacao": "Phishing é a técnica de \"pescar\" dados da vítima se passando por entidade confiável. Ransomware sequestra dados, worm se propaga sozinho, e firewall e backup são mecanismos de proteção."}, {"materia": "inf", "texto_base": null, "enunciado": "O código malicioso que criptografa os arquivos da vítima e exige pagamento para liberar o acesso é o", "opcoes": ["ransomware.", "keylogger.", "spyware.", "adware.", "rootkit."], "gabarito": 0, "explicacao": "Ransomware sequestra os dados e cobra resgate, em geral em criptomoeda. Spyware espiona, adware exibe propaganda, keylogger captura o que é digitado e rootkit esconde a presença do invasor."}, {"materia": "inf", "texto_base": null, "enunciado": "Ao acessar um site cujo endereço começa com \"https\", o usuário sabe que", "opcoes": ["o site é oficial do governo.", "o computador está protegido contra vírus.", "a comunicação entre o navegador e o servidor é criptografada.", "a página não usa cookies.", "o site está livre de qualquer golpe."], "gabarito": 2, "explicacao": "O HTTPS usa TLS para criptografar a comunicação. Isso não garante que o site seja legítimo: sites falsos também podem usar HTTPS."}, {"materia": "inf", "texto_base": null, "enunciado": "No backup incremental, são copiados", "opcoes": ["apenas os arquivos do sistema operacional.", "apenas os arquivos criados ou alterados desde o último backup, de qualquer tipo.", "todos os arquivos, sempre.", "somente os arquivos apagados.", "os arquivos alterados desde o último backup completo, acumulando as mudanças."], "gabarito": 1, "explicacao": "O incremental copia o que mudou desde o último backup de qualquer tipo. O diferencial copia tudo o que mudou desde o último backup completo."}, {"materia": "inf", "texto_base": null, "enunciado": "Em uma planilha do Excel, as células A1, A2 e A3 contêm, respectivamente, 4, 6 e 11. O resultado da fórmula =MÉDIA(A1:A3) é", "opcoes": ["11", "7", "6", "3", "21"], "gabarito": 1, "explicacao": "(4 + 6 + 11) ÷ 3 = 21 ÷ 3 = 7. O valor 21 seria a soma, e 6 é a mediana."}, {"materia": "const", "texto_base": null, "enunciado": "Segundo a Constituição Federal, a casa é asilo inviolável do indivíduo, e nela ninguém pode penetrar sem consentimento do morador, salvo", "opcoes": ["por determinação judicial, a qualquer hora do dia ou da noite.", "por requisição do Ministério Público, durante o dia.", "em caso de suspeita de crime, sem necessidade de ordem judicial.", "em caso de flagrante delito ou desastre, para prestar socorro ou, durante o dia, por determinação judicial.", "por ordem do delegado de polícia, a qualquer hora."], "gabarito": 3, "explicacao": "CF, art. 5º, XI. A ordem judicial só autoriza a entrada durante o dia. Flagrante, desastre e socorro autorizam a qualquer hora."}, {"materia": "const", "texto_base": null, "enunciado": "De acordo com a Constituição Federal, ninguém será preso senão", "opcoes": ["em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar.", "por determinação do Ministério Público ou da autoridade policial.", "após sentença condenatória transitada em julgado, sem exceção.", "por ordem escrita de qualquer autoridade policial.", "em flagrante delito ou por ordem verbal de autoridade judiciária."], "gabarito": 0, "explicacao": "CF, art. 5º, LXI."}, {"materia": "const", "texto_base": null, "enunciado": "O remédio constitucional cabível sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder, é o", "opcoes": ["habeas corpus.", "habeas data.", "mandado de segurança.", "ação popular.", "mandado de injunção."], "gabarito": 0, "explicacao": "CF, art. 5º, LXVIII."}, {"materia": "const", "texto_base": null, "enunciado": "Entre os órgãos listados no art. 144 da Constituição Federal como responsáveis pela segurança pública, NÃO se inclui a", "opcoes": ["Polícia Ferroviária Federal.", "polícia civil.", "Polícia Rodoviária Federal.", "polícia penal.", "Agência Brasileira de Inteligência (Abin)."], "gabarito": 4, "explicacao": "O art. 144 lista a polícia federal, a rodoviária federal, a ferroviária federal, as polícias civis, as polícias militares e corpos de bombeiros militares e as polícias penais. A Abin não está nessa lista."}, {"materia": "const", "texto_base": null, "enunciado": "Segundo a Constituição Federal, às polícias civis, dirigidas por delegados de polícia de carreira, incumbem", "opcoes": ["a apuração de todas as infrações penais, inclusive as militares.", "as funções de polícia judiciária e a apuração de infrações penais, exceto as militares, ressalvada a competência da União.", "o policiamento ostensivo e a preservação da ordem pública.", "o patrulhamento ostensivo das rodovias federais.", "a segurança dos estabelecimentos penais."], "gabarito": 1, "explicacao": "CF, art. 144, § 4º. O policiamento ostensivo cabe às polícias militares, as rodovias federais à PRF e os estabelecimentos penais às polícias penais."}, {"materia": "const", "texto_base": null, "enunciado": "De acordo com a Constituição Federal, o preso será informado de seus direitos, entre os quais o de", "opcoes": ["ser solto em 24 horas, independentemente de decisão judicial.", "não ser algemado em nenhuma hipótese.", "não ser identificado criminalmente em nenhum caso.", "permanecer calado, sendo-lhe assegurada a assistência da família e de advogado.", "escolher a delegacia em que ficará detido."], "gabarito": 3, "explicacao": "CF, art. 5º, LXIII."}, {"materia": "const", "texto_base": null, "enunciado": "Segundo a Constituição Federal, constituem crimes inafiançáveis e imprescritíveis", "opcoes": ["o homicídio qualificado e o latrocínio.", "o terrorismo e os crimes hediondos.", "a prática do racismo e a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático.", "a tortura e o tráfico ilícito de entorpecentes.", "todos os crimes contra a vida."], "gabarito": 2, "explicacao": "CF, art. 5º, XLII e XLIV. A tortura, o tráfico, o terrorismo e os hediondos são inafiançáveis e insuscetíveis de graça ou anistia (inciso XLIII), mas não são imprescritíveis."}, {"materia": "const", "texto_base": null, "enunciado": "Para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público, a Constituição prevê o", "opcoes": ["mandado de segurança coletivo.", "direito de petição apenas.", "habeas corpus.", "habeas data.", "mandado de injunção."], "gabarito": 3, "explicacao": "CF, art. 5º, LXXII."}, {"materia": "adm", "texto_base": null, "enunciado": "NÃO é princípio expresso no caput do art. 37 da Constituição Federal o princípio da", "opcoes": ["publicidade.", "legalidade.", "impessoalidade.", "razoabilidade.", "eficiência."], "gabarito": 3, "explicacao": "O caput traz legalidade, impessoalidade, moralidade, publicidade e eficiência. A razoabilidade é princípio implícito na Constituição e expresso na Lei 9.784/1999."}, {"materia": "adm", "texto_base": null, "enunciado": "São atributos tradicionalmente apontados pela doutrina para o poder de polícia:", "opcoes": ["discricionariedade, autoexecutoriedade e coercibilidade.", "imprescritibilidade, inalienabilidade e impenhorabilidade.", "hierarquia, disciplina e subordinação.", "tipicidade, culpabilidade e ilicitude.", "gratuidade, continuidade e modicidade."], "gabarito": 0, "explicacao": "A doutrina clássica (Hely Lopes Meirelles) aponta esses três atributos do poder de polícia."}, {"materia": "adm", "texto_base": null, "enunciado": "Sobre o desfazimento dos atos administrativos, é correto afirmar que", "opcoes": ["a Administração pode anular seus atos ilegais e revogar os inoportunos ou inconvenientes, respeitados os direitos adquiridos.", "a anulação produz efeitos apenas a partir da data em que é feita, em qualquer caso.", "o Judiciário pode revogar atos do Executivo por conveniência.", "somente o Poder Judiciário pode anular atos administrativos.", "a revogação é feita por motivo de ilegalidade."], "gabarito": 0, "explicacao": "Súmula 473 do STF. A anulação, por ilegalidade, em regra retroage. A revogação, por conveniência e oportunidade, só pode ser feita pela própria Administração e produz efeitos daí em diante."}, {"materia": "adm", "texto_base": null, "enunciado": "Após as alterações da Lei 14.230/2021, a Lei de Improbidade Administrativa (Lei 8.429/1992) passou a exigir, para a configuração do ato de improbidade,", "opcoes": ["enriquecimento ilícito comprovado em qualquer caso.", "condenação criminal prévia do agente.", "dano ao erário em todas as hipóteses.", "dolo, não havendo mais improbidade na modalidade culposa.", "apenas culpa grave, em todas as modalidades."], "gabarito": 3, "explicacao": "Lei 8.429/1992, art. 1º, §§ 1º a 3º, com redação da Lei 14.230/2021: só configuram improbidade as condutas dolosas."}, {"materia": "adm", "texto_base": null, "enunciado": "Pela Constituição Federal, as pessoas jurídicas de direito público e as de direito privado prestadoras de serviço público respondem pelos danos que seus agentes, nessa qualidade, causarem a terceiros", "opcoes": ["de forma subsidiária, após a cobrança do agente.", "apenas quando o agente for condenado criminalmente.", "somente nos casos de dolo do agente.", "somente se comprovada a culpa do agente.", "de forma objetiva, assegurado o direito de regresso contra o agente nos casos de dolo ou culpa."], "gabarito": 4, "explicacao": "CF, art. 37, § 6º."}, {"materia": "adm", "texto_base": null, "enunciado": "O abuso de poder, gênero, compreende as espécies", "opcoes": ["poder vinculado e poder discricionário.", "poder hierárquico e poder disciplinar.", "concussão e prevaricação.", "excesso de poder e desvio de finalidade.", "anulação e revogação."], "gabarito": 3, "explicacao": "No excesso de poder, o agente vai além da sua competência. No desvio de finalidade, ele age dentro da competência, mas visando a fim diverso do interesse público previsto em lei."}, {"materia": "pen", "texto_base": null, "enunciado": "Segundo o Código Penal, entende-se em legítima defesa quem,", "opcoes": ["repele agressão passada, para vingar ofensa sofrida.", "pratica o fato para salvar de perigo atual, que não provocou por sua vontade, direito próprio ou alheio.", "age em estrito cumprimento de dever legal.", "usa qualquer meio disponível contra agressão futura e incerta.", "usando moderadamente dos meios necessários, repele injusta agressão, atual ou iminente, a direito seu ou de outrem."], "gabarito": 4, "explicacao": "CP, art. 25. A segunda alternativa descreve o estado de necessidade (art. 24)."}, {"materia": "pen", "texto_base": null, "enunciado": "NÃO é causa de exclusão da ilicitude prevista no art. 23 do Código Penal:", "opcoes": ["coação moral irresistível.", "estrito cumprimento de dever legal.", "estado de necessidade.", "legítima defesa.", "exercício regular de direito."], "gabarito": 0, "explicacao": "A coação moral irresistível (art. 22) exclui a culpabilidade, por inexigibilidade de conduta diversa, e não a ilicitude."}, {"materia": "pen", "texto_base": null, "enunciado": "Considera-se o crime tentado quando,", "opcoes": ["o agente, após consumado o crime, repara o dano.", "iniciada a execução, não se consuma por circunstâncias alheias à vontade do agente.", "o agente desiste voluntariamente de prosseguir na execução.", "o resultado ocorre por culpa do agente.", "o agente apenas planeja o crime, sem iniciar a execução."], "gabarito": 1, "explicacao": "CP, art. 14, II. Salvo disposição em contrário, a tentativa é punida com a pena do crime consumado diminuída de um a dois terços."}, {"materia": "pen", "texto_base": null, "enunciado": "O agente que, voluntariamente, desiste de prosseguir na execução do crime", "opcoes": ["só responde pelos atos já praticados.", "responde pelo crime tentado, com pena reduzida.", "responde pelo crime consumado.", "fica isento de qualquer pena, mesmo pelos atos praticados.", "responde em dobro pelos atos praticados."], "gabarito": 0, "explicacao": "CP, art. 15: desistência voluntária e arrependimento eficaz."}, {"materia": "pen", "texto_base": null, "enunciado": "O funcionário público que exige, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida comete o crime de", "opcoes": ["concussão.", "peculato.", "corrupção passiva.", "prevaricação.", "corrupção ativa."], "gabarito": 0, "explicacao": "CP, art. 316. Na corrupção passiva (art. 317), o verbo é solicitar ou receber, e não exigir."}, {"materia": "pen", "texto_base": null, "enunciado": "Retardar ou deixar de praticar, indevidamente, ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal, configura o crime de", "opcoes": ["advocacia administrativa.", "condescendência criminosa.", "peculato.", "prevaricação.", "concussão."], "gabarito": 3, "explicacao": "CP, art. 319."}, {"materia": "pen", "texto_base": null, "enunciado": "O que diferencia o roubo do furto é que, no roubo,", "opcoes": ["o crime é praticado durante a noite.", "a coisa é subtraída de órgão público.", "a subtração ocorre mediante grave ameaça ou violência à pessoa, ou depois de havê-la reduzido à impossibilidade de resistência.", "o agente é funcionário público.", "a coisa subtraída tem valor elevado."], "gabarito": 2, "explicacao": "CP, art. 157. O furto (art. 155) é a subtração sem violência ou grave ameaça à pessoa."}, {"materia": "pen", "texto_base": null, "enunciado": "Segundo o Código Penal, os menores de 18 anos são", "opcoes": ["imputáveis apenas em crimes hediondos.", "penalmente inimputáveis, ficando sujeitos às normas da legislação especial.", "imputáveis a partir dos 16 anos em qualquer crime.", "semi-imputáveis.", "imputáveis, com pena reduzida."], "gabarito": 1, "explicacao": "CP, art. 27 e CF, art. 228. A legislação especial é o Estatuto da Criança e do Adolescente."}, {"materia": "ppen", "texto_base": null, "enunciado": "Sobre o inquérito policial, é correto afirmar que", "opcoes": ["nele é obrigatório o contraditório pleno.", "a autoridade policial não poderá mandar arquivar os autos do inquérito.", "é indispensável para o oferecimento da denúncia.", "a autoridade policial pode arquivá-lo quando não houver indícios.", "só pode ser instaurado por requisição judicial."], "gabarito": 1, "explicacao": "CPP, art. 17. O inquérito é dispensável quando já houver elementos para a denúncia, tem natureza inquisitiva e pode ser instaurado de ofício pela autoridade policial nos crimes de ação pública."}, {"materia": "ppen", "texto_base": null, "enunciado": "Pelo art. 10 do Código de Processo Penal, o inquérito deverá terminar, se o indiciado estiver preso, no prazo de", "opcoes": ["10 dias.", "15 dias.", "30 dias.", "5 dias.", "60 dias."], "gabarito": 0, "explicacao": "CPP, art. 10: 10 dias se o indiciado estiver preso e 30 dias se estiver solto."}, {"materia": "ppen", "texto_base": null, "enunciado": "Considera-se em flagrante delito quem é perseguido, logo após, pela autoridade, pelo ofendido ou por qualquer pessoa, em situação que faça presumir ser autor da infração. Essa modalidade é chamada pela doutrina de flagrante", "opcoes": ["esperado.", "impróprio (ou quase flagrante).", "próprio.", "preparado.", "presumido (ou ficto)."], "gabarito": 1, "explicacao": "CPP, art. 302, III. O flagrante próprio é o dos incisos I e II e o presumido o do inciso IV. O preparado é ilegal (Súmula 145 do STF)."}, {"materia": "ppen", "texto_base": null, "enunciado": "Segundo o Código de Processo Penal, em relação a quem for encontrado em flagrante delito,", "opcoes": ["só o Ministério Público pode determinar a prisão.", "qualquer do povo poderá e as autoridades policiais e seus agentes deverão prendê-lo.", "a prisão depende de ordem judicial prévia.", "somente as autoridades policiais podem prendê-lo.", "qualquer do povo deverá prendê-lo, sob pena de crime."], "gabarito": 1, "explicacao": "CPP, art. 301: o flagrante é facultativo para qualquer do povo e obrigatório para a autoridade policial e seus agentes."}, {"materia": "ppen", "texto_base": null, "enunciado": "Na ação penal pública condicionada à representação, o ofendido decai do direito de representação se não o exercer, em regra, no prazo de", "opcoes": ["6 meses, contados do dia em que vier a saber quem é o autor do crime.", "30 dias, contados do fato.", "6 meses, contados da data do fato.", "1 ano, contado do fato.", "2 anos, contados do conhecimento da autoria."], "gabarito": 0, "explicacao": "CPP, art. 38."}, {"materia": "ppen", "texto_base": null, "enunciado": "A autoridade policial somente poderá conceder fiança nos casos de infração cuja pena privativa de liberdade máxima", "opcoes": ["seja de detenção, qualquer que seja o máximo.", "não seja superior a 8 anos.", "não seja superior a 2 anos.", "não seja superior a 6 anos.", "não seja superior a 4 anos."], "gabarito": 4, "explicacao": "CPP, art. 322. Nos demais casos, a fiança é requerida ao juiz."}, {"materia": "ppen", "texto_base": null, "enunciado": "Segundo o Código de Processo Penal, cadeia de custódia é", "opcoes": ["o prazo de guarda dos autos do inquérito arquivado.", "a ordem de oitiva das testemunhas no inquérito.", "a cela onde o preso aguarda a audiência de custódia.", "o conjunto de procedimentos usados para manter e documentar a história cronológica do vestígio coletado.", "o registro dos policiais que participaram da prisão em flagrante."], "gabarito": 3, "explicacao": "CPP, art. 158-A, incluído pela Lei 13.964/2019."}, {"materia": "leg", "texto_base": null, "enunciado": "Segundo a Lei Maria da Penha (Lei 11.340/2006), são formas de violência doméstica e familiar contra a mulher, entre outras, as violências", "opcoes": ["física e sexual, apenas.", "patrimonial e moral, apenas quando houver lesão corporal.", "psicológica, apenas quando houver ameaça escrita.", "física, verbal e institucional, apenas.", "física, psicológica, sexual, patrimonial e moral."], "gabarito": 4, "explicacao": "Lei 11.340/2006, art. 7º."}, {"materia": "leg", "texto_base": null, "enunciado": "Segundo a Lei 9.455/1997, a condenação por crime de tortura acarretará", "opcoes": ["apenas multa administrativa.", "a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.", "a perda do cargo somente se o juiz declarar fundamentadamente.", "a suspensão do cargo por 30 dias.", "a interdição para o cargo pelo mesmo prazo da pena."], "gabarito": 1, "explicacao": "Lei 9.455/1997, art. 1º, § 5º. O efeito é automático."}, {"materia": "leg", "texto_base": null, "enunciado": "Segundo a Lei de Abuso de Autoridade (Lei 13.869/2019),", "opcoes": ["a lei não se aplica a servidores policiais.", "basta a irregularidade do ato para configurar o crime, sem finalidade específica.", "as condutas são punidas também na forma culposa.", "a divergência na interpretação de lei ou na avaliação de fatos e provas, por si só, não configura abuso de autoridade.", "o crime só existe se houver dano patrimonial ao Estado."], "gabarito": 3, "explicacao": "Lei 13.869/2019, art. 1º, §§ 1º e 2º: é preciso finalidade específica (prejudicar outrem, beneficiar a si ou a terceiro, ou mero capricho ou satisfação pessoal)."}, {"materia": "leg", "texto_base": null, "enunciado": "Pela Constituição Federal e pela Lei 8.072/1990, são equiparados a hediondos, sendo insuscetíveis de anistia, graça, indulto e fiança, os crimes de", "opcoes": ["homicídio simples e lesão corporal leve.", "furto, estelionato e receptação.", "tortura, tráfico ilícito de entorpecentes e drogas afins e terrorismo.", "racismo e injúria.", "corrupção passiva e peculato."], "gabarito": 2, "explicacao": "CF, art. 5º, XLIII e Lei 8.072/1990, art. 2º."}, {"materia": "dh", "texto_base": null, "enunciado": "Segundo a Constituição Federal, os tratados e convenções internacionais sobre direitos humanos que forem aprovados em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão", "opcoes": ["equivalentes às leis complementares.", "dispensados de promulgação.", "equivalentes às emendas constitucionais.", "equivalentes às leis ordinárias.", "inferiores às leis ordinárias."], "gabarito": 2, "explicacao": "CF, art. 5º, § 3º, incluído pela EC 45/2004. Os tratados de direitos humanos aprovados sem esse rito têm status supralegal, segundo o STF."}, {"materia": "dh", "texto_base": null, "enunciado": "Considerando a Convenção Americana sobre Direitos Humanos (Pacto de San José da Costa Rica) e a jurisprudência do STF, é correto afirmar que", "opcoes": ["é ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito.", "a prisão civil por qualquer dívida é permitida.", "a Convenção não foi incorporada ao direito brasileiro.", "é permitida a prisão civil do depositário infiel.", "é proibida a prisão civil do devedor de alimentos."], "gabarito": 0, "explicacao": "Súmula Vinculante 25. A Convenção (art. 7.7) só admite a prisão civil do devedor de alimentos."}, {"materia": "dh", "texto_base": null, "enunciado": "Segundo a Súmula Vinculante 11 do STF, o uso de algemas só é lícito", "opcoes": ["sempre que o preso for conduzido à delegacia.", "somente por ordem judicial prévia.", "em casos de resistência e de fundado receio de fuga ou de perigo à integridade física própria ou alheia, justificada a excepcionalidade por escrito.", "apenas para presos condenados definitivamente.", "a critério do policial, sem necessidade de justificativa."], "gabarito": 2, "explicacao": "Súmula Vinculante 11, sob pena de responsabilidade disciplinar, civil e penal do agente e de nulidade da prisão ou do ato processual."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('policial', date '2026-10-25', 'Simulado 1 · Policial', 'AOCP', 180, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'policial' and s.data = date '2026-10-25' group by s.id;
